before:
import { test, expect } from "@playwright/test";

const baseUrl = "https://teskerti.tn";

test.describe("Consultation du programme mis en avant depuis la page d'accueil", () => {
  test("Vérification de la présence du bouton dans la section héro", async ({ page }) => {
    // Given l'utilisateur est sur la page d'accueil du site
    await page.goto(baseUrl);

    // Then la section héro affiche un bouton « Réservez vos billets »
    await expect(page.getByRole("button", { name: "Réservez vos billets" })).toBeVisible();
  });
});

